  const admin=['entregar','receber_devolucao','vincular_orcamento','faturar','tratar_ocorrencias'].some(can),tabs=admin?[['entregar','A entregar'],['entregues','Entregues / devoluções'],['historico','Histórico']]:[['minhas','Minhas peças'],['historico','Histórico']];
