  root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{ctx.tab=b.dataset.tab;if(ctx.tab==='quarentena'){renderCentralList();}else renderCentral();});root.querySelector('#mat-new')?.addEventListener('click',()=>newRequest().catch(e=>alert(e.message)));root.querySelector('#mat-prepare').onclick=async()=>{try{await sync();await load(true);await renderCentral();}catch(e){alert(e.message);}};root.querySelector('#mat-export').onclick=()=>exportCSV();root.querySelector('#mat-config')?.addEventListener('click',()=>form('Prazo de conferência',field('testDays','Dias para conferir peças fora do estoque','number',5,'min="1" max="30" required'),v=>execute('CONFIG',v)));root.querySelectorAll('#mat-search,#mat-status,#mat-date').forEach(x=>x.oninput=()=>renderCentralList());await bindQueue(root);renderCentralList();
